1	"use server";
2	
3	import { refresh } from "next/cache";
4	import { db } from "@/lib/db";
5	import { getAdminUser } from "@/lib/auth";
6	import { NOTE_MAX, type NoteFormState } from "./ui";
7	
8	// Writing a support note is the only mutation this inbox performs. Everything
9	// else on these pages reads.
10	//
11	// A "use server" file may only export async functions, so NOTE_MAX and the
12	// form-state type live in ./ui.tsx and are imported (the type as a type-only
13	// import, so nothing React-shaped is dragged into the action bundle).
14	
15	export async function addSupportNote(
16	  _prev: NoteFormState,
17	  formData: FormData,
18	): Promise<NoteFormState> {
19	  // Server Functions are reachable by direct POST, not only through this UI —
20	  // so the admin check happens HERE, not merely on the page that renders the
21	  // form. Same reason getAdminUser() is called on every admin page: a layout
22	  // is not an authorization boundary.
23	  const admin = await getAdminUser();
24	  if (!admin) return { error: "You are not signed in as an admin.", ok: false };
25	
26	  const rawUserId = formData.get("userId");
27	  const rawBody = formData.get("body");
28	  const userId = typeof rawUserId === "string" ? rawUserId : "";
29	  const body = typeof rawBody === "string" ? rawBody.trim() : "";
30	
31	  if (!userId) return { error: "Missing the customer this note is about.", ok: false };
32	  if (!body) return { error: "A note needs something in it.", ok: false };
33	  if (body.length > NOTE_MAX) {
34	    return {
35	      error: `That is ${body.length} characters — keep a note under ${NOTE_MAX}. Summarise rather than paste.`,
36	      ok: false,
37	    };
38	  }
39	
40	  // Verify the target exists rather than letting the foreign key throw: a 500
41	  // on a stale tab is a worse answer than a sentence.
42	  const user = await db.user.findUnique({ where: { id: userId }, select: { id: true } });
43	  if (!user) return { error: "That customer no longer exists.", ok: false };
44	
45	  await db.supportNote.create({
46	    // authorEmail comes from the session, never from the form. Attribution
47	    // nobody can spoof is the whole point of recording it.
48	    data: { userId: user.id, authorEmail: admin.email, body },
49	  });
50	
51	  // Re-render the current route so the new note appears above the form without
52	  // a manual reload.
53	  refresh();
54	
55	  return { error: null, ok: true };
56	}
