1	import Link from "next/link";
2	import { notFound } from "next/navigation";
3	import { db } from "@/lib/db";
4	import { getAdminUser } from "@/lib/auth";
5	import { EVENTS } from "@/lib/events";
6	import {
7	  Empty,
8	  Panel,
9	  StatTile,
10	  TableFrame,
11	  Th,
12	  formatDateTime,
13	  truncate,
14	} from "../users/ui";
15	import {
16	  Bar,
17	  Caution,
18	  RatingPill,
19	  REASONS,
20	  buttonClass,
21	  controlClass,
22	  isReasonId,
23	  reasonLabel,
24	} from "./ui";
25	
26	export const dynamic = "force-dynamic";
27	
28	// The individual side of the satisfaction percentage on /admin. That number is
29	// the temperature; this page is the thermometer reading you can act on — one
30	// row per thumbs-up/down, with the reason the customer picked.
31	//
32	// Everything here is derived from `build.rated` events (lib/events.ts, written
33	// by app/api/feedback/route.ts). Nothing on this page writes to the stream.
34	
35	/**
36	 * How many ratings are pulled into memory. Ratings are low-volume by nature
37	 * (a fraction of builds get rated at all), and the aggregates below — the
38	 * reason breakdown and the repair cross-tab — have to be computed over the
39	 * SAME set that the table shows, or the panels would quietly disagree with
40	 * each other. One bounded read, no query in a loop.
41	 */
42	const WINDOW = 500;
43	
44	/** Rows rendered after filtering. The window above is the honest denominator. */
45	const ROW_LIMIT = 200;
46	
47	type Rated = {
48	  id: string;
49	  createdAt: Date;
50	  userId: string | null;
51	  rating: "up" | "down" | null;
52	  reason: string | null;
53	  model: string | null;
54	  buildId: string | null;
55	  projectId: string | null;
56	  /** null when the event predates the prop, not zero — the two are different facts. */
57	  repairAttempts: number | null;
58	};
59	
60	function str(v: unknown): string | null {
61	  return typeof v === "string" && v.length > 0 ? v : null;
62	}
63	
64	function num(v: unknown): number | null {
65	  return typeof v === "number" && Number.isFinite(v) ? v : null;
66	}
67	
68	/**
69	 * Props are Json and therefore untrusted shape-wise: an event written before a
70	 * prop existed simply lacks it. Every field is read defensively so one odd row
71	 * cannot blank the page.
72	 */
73	function parseRated(row: { id: string; createdAt: Date; userId: string | null; props: unknown }): Rated {
74	  const p =
75	    row.props !== null && typeof row.props === "object" && !Array.isArray(row.props)
76	      ? (row.props as Record<string, unknown>)
77	      : {};
78	  const rating = str(p.rating);
79	  return {
80	    id: row.id,
81	    createdAt: row.createdAt,
82	    userId: row.userId,
83	    rating: rating === "up" || rating === "down" ? rating : null,
84	    reason: str(p.reason),
85	    model: str(p.model),
86	    buildId: str(p.buildId),
87	    projectId: str(p.projectId),
88	    repairAttempts: num(p.repairAttempts),
89	  };
90	}
91	
92	function first(v: string | string[] | undefined): string {
93	  if (Array.isArray(v)) return v[0] ?? "";
94	  return v ?? "";
95	}
96	
97	function href(params: { rating: string; reason: string }): string {
98	  const sp = new URLSearchParams();
99	  if (params.rating) sp.set("rating", params.rating);
100	  if (params.reason) sp.set("reason", params.reason);
101	  const qs = sp.toString();
102	  return qs ? `/admin/feedback?${qs}` : "/admin/feedback";
103	}
104	
105	function pct(part: number, whole: number): number | null {
106	  return whole === 0 ? null : Math.round((part / whole) * 1000) / 10;
107	}
108	
109	/** One row of the repair cross-tab. */
110	type Bucket = { label: string; hint: string; up: number; down: number };
111	
112	export default async function AdminFeedbackPage({
113	  searchParams,
114	}: {
115	  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
116	}) {
117	  // Defense in depth — app/admin/layout.tsx is the primary gate, but a layout
118	  // is not an authorization boundary on its own. 404 rather than redirect, so
119	  // a non-admin who reaches this path learns nothing from it.
120	  if (!(await getAdminUser())) notFound();
121	
122	  const sp = await searchParams;
123	  const ratingRaw = first(sp.rating);
124	  const rating = ratingRaw === "up" || ratingRaw === "down" ? ratingRaw : "";
125	  const reasonRaw = first(sp.reason);
126	  const reason = reasonRaw === "none" || isReasonId(reasonRaw) ? reasonRaw : "";
127	
128	  const [total, rows] = await Promise.all([
129	    db.event.count({ where: { name: EVENTS.buildRated } }),
130	    db.event.findMany({
131	      where: { name: EVENTS.buildRated },
132	      // Served straight off the @@index([name, createdAt]) on Event.
133	      orderBy: { createdAt: "desc" },
134	      take: WINDOW,
135	      select: { id: true, createdAt: true, userId: true, props: true },
136	    }),
137	  ]);
138	
139	  const ratings = rows.map(parseRated);
140	
141	  // Two id→label lookups for the whole window, not one query per row.
142	  const userIds = [...new Set(ratings.map((r) => r.userId).filter((v): v is string => v !== null))];
143	  const projectIds = [
144	    ...new Set(ratings.map((r) => r.projectId).filter((v): v is string => v !== null)),
145	  ];
146	
147	  const [users, projects] = await Promise.all([
148	    userIds.length
149	      ? db.user.findMany({ where: { id: { in: userIds } }, select: { id: true, email: true } })
150	      : Promise.resolve([]),
151	    projectIds.length
152	      ? db.project.findMany({ where: { id: { in: projectIds } }, select: { id: true, name: true } })
153	      : Promise.resolve([]),
154	  ]);
155	
156	  const emailById = new Map(users.map((u) => [u.id, u.email]));
157	  const projectById = new Map(projects.map((p) => [p.id, p.name]));
158	
159	  // ── Aggregates, over the whole window rather than the filtered view ──────
160	  // Filtering the breakdown by the filter it is meant to explain would make
161	  // every bar 100%.
162	  const up = ratings.filter((r) => r.rating === "up").length;
163	  const down = ratings.filter((r) => r.rating === "down").length;
164	  const rated = up + down;
165	
166	  const reasonCounts = REASONS.map((r) => ({
167	    ...r,
168	    count: ratings.filter((x) => x.reason === r.id).length,
169	  }));
170	  const noReason = ratings.filter((r) => r.rating === "down" && r.reason === null).length;
171	  const maxReason = Math.max(0, ...reasonCounts.map((r) => r.count), noReason);
172	  const withReason = reasonCounts.reduce((a, b) => a + b.count, 0);
173	
174	  // ── The question this page exists to answer ──────────────────────────────
175	  // A thumbs-down on a build that needed a repair pass and a thumbs-down on a
176	  // build that compiled first try are two different bugs. The first says the
177	  // repair loop ships something that limps (reliability). The second says the
178	  // output was fine mechanically and still wasn't what they asked for
179	  // (quality). Averaging them together hides both.
180	  const clean = ratings.filter((r) => r.repairAttempts === 0);
181	  const repaired = ratings.filter((r) => r.repairAttempts !== null && r.repairAttempts > 0);
182	  const unknownRepairs = ratings.filter((r) => r.repairAttempts === null);
183	
184	  const buckets: Bucket[] = [
185	    {
186	      label: "Compiled first try",
187	      hint: "repairAttempts = 0",
188	      up: clean.filter((r) => r.rating === "up").length,
189	      down: clean.filter((r) => r.rating === "down").length,
190	    },
191	    {
192	      label: "Needed a repair pass",
193	      hint: "repairAttempts ≥ 1",
194	      up: repaired.filter((r) => r.rating === "up").length,
195	      down: repaired.filter((r) => r.rating === "down").length,
196	    },
197	  ];
198	  if (unknownRepairs.length > 0) {
199	    buckets.push({
200	      label: "Not recorded",
201	      hint: "event has no repairAttempts prop",
202	      up: unknownRepairs.filter((r) => r.rating === "up").length,
203	      down: unknownRepairs.filter((r) => r.rating === "down").length,
204	    });
205	  }
206	
207	  const cleanRated = buckets[0].up + buckets[0].down;
208	  const repairedRated = buckets[1].up + buckets[1].down;
209	  const cleanDownRate = pct(buckets[0].down, cleanRated);
210	  const repairedDownRate = pct(buckets[1].down, repairedRated);
211	  const gap =
212	    cleanDownRate !== null && repairedDownRate !== null ? repairedDownRate - cleanDownRate : null;
213	
214	  // n is small for a long while after launch. Say so rather than letting three
215	  // ratings read as a finding.
216	  const enoughToRead = cleanRated >= 10 && repairedRated >= 10;
217	
218	  // ── The filtered view ────────────────────────────────────────────────────
219	  const filtered = ratings.filter((r) => {
220	    if (rating && r.rating !== rating) return false;
221	    if (reason === "none") return r.reason === null;
222	    if (reason && r.reason !== reason) return false;
223	    return true;
224	  });
225	  const visible = filtered.slice(0, ROW_LIMIT);
226	  const filtering = rating !== "" || reason !== "";
227	
228	  return (
229	    <div className="mx-auto max-w-6xl px-6 py-10">
230	      <div className="mb-8">
231	        <Link
232	          href="/admin"
233	          className="rounded text-xs text-black/50 underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:text-white/50 dark:focus-visible:ring-white/40"
234	        >
235	          ← kodely admin
236	        </Link>
237	        <div className="mt-1 text-lg font-semibold tracking-tight">Support inbox</div>
238	        <p className="text-sm text-black/60 dark:text-white/60">
239	          Every individual build rating, newest first. /admin gives the satisfaction percentage;
240	          this is what is actually behind it.{" "}
241	          <Link
242	            href="/admin/feedback/notes"
243	            className="rounded underline underline-offset-4 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40"
244	          >
245	            Operator notes →
246	          </Link>
247	        </p>
248	      </div>
249	
250	      {total === 0 ? (
251	        <Caution title="Nothing recorded yet — do not read this as good news">
252	          <p>
253	            There are zero <code className="font-mono text-xs">build.rated</code> events in the
254	            database. Ratings only started being collected very recently, and the event stream holds
255	            nothing from before that shipped.
256	          </p>
257	          <p className="mt-2">
258	            An empty inbox here is indistinguishable from a page where everybody is happy. It is
259	            neither: it is a page with no data. Every count, percentage and bar below is computed
260	            over an empty set.
261	          </p>
262	        </Caution>
263	      ) : null}
264	
265	      <div className="mb-8 grid grid-cols-2 gap-4 sm:grid-cols-4">
266	        <StatTile
267	          label="Ratings in window"
268	          value={rated}
269	          hint={
270	            total > ratings.length
271	              ? `most recent ${ratings.length} of ${total}`
272	              : total === 0
273	                ? "nothing recorded yet"
274	                : "the whole stream"
275	          }
276	        />
277	        <StatTile
278	          label="Thumbs down"
279	          value={<span className={down > 0 ? "text-red-600 dark:text-red-400" : ""}>{down}</span>}
280	          hint={rated === 0 ? "no ratings yet" : `${pct(down, rated)}% of ratings`}
281	        />
282	        <StatTile
283	          label="With a reason"
284	          value={withReason}
285	          hint={
286	            down === 0 ? "no thumbs-down yet" : `${noReason} thumbs-down left without one`
287	          }
288	        />
289	        <StatTile
290	          label="Needed a repair pass"
291	          value={repaired.length}
292	          tone={repaired.length > 0 ? "warn" : undefined}
293	          hint={
294	            ratings.length === 0
295	              ? "no ratings yet"
296	              : `${pct(repaired.length, ratings.length)}% of rated builds`
297	          }
298	        />
299	      </div>
300	
301	      <div className="mb-8 grid gap-4 lg:grid-cols-2">
302	        <Panel
303	          title="Rating vs. repair pass"
304	          subtitle="Are the thumbs-down builds the ones that needed a second generation to compile? A quality problem and a reliability problem look identical in the satisfaction percentage and need opposite fixes."
305	        >
306	          {rated === 0 ? (
307	            <Empty>Nothing to correlate — no build has been rated yet.</Empty>
308	          ) : (
309	            <>
310	              <TableFrame>
311	                <thead>
312	                  <tr className="border-b border-black/10 text-xs text-black/50 dark:border-white/10 dark:text-white/50">
313	                    <Th>Build</Th>
314	                    <Th align="right">Rated</Th>
315	                    <Th align="right">Up</Th>
316	                    <Th align="right">Down</Th>
317	                    <Th align="right">Down rate</Th>
318	                  </tr>
319	                </thead>
320	                <tbody className="divide-y divide-black/10 dark:divide-white/10">
321	                  {buckets.map((b) => {
322	                    const n = b.up + b.down;
323	                    const rate = pct(b.down, n);
324	                    return (
325	                      <tr key={b.label}>
326	                        <td className="px-4 py-2">
327	                          {b.label}
328	                          <div className="font-mono text-xs text-black/40 dark:text-white/40">
329	                            {b.hint}
330	                          </div>
331	                        </td>
332	                        <td className="px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
333	                          {n}
334	                        </td>
335	                        <td className="px-4 py-2 text-right tabular-nums text-emerald-600 dark:text-emerald-400">
336	                          {b.up}
337	                        </td>
338	                        <td className="px-4 py-2 text-right tabular-nums text-red-600 dark:text-red-400">
339	                          {b.down}
340	                        </td>
341	                        <td className="px-4 py-2 text-right font-medium tabular-nums">
342	                          {rate === null ? (
343	                            <span className="text-black/30 dark:text-white/30">—</span>
344	                          ) : (
345	                            `${rate}%`
346	                          )}
347	                        </td>
348	                      </tr>
349	                    );
350	                  })}
351	                </tbody>
352	              </TableFrame>
353	
354	              <p className="mt-3 text-xs text-black/60 dark:text-white/60">
355	                {!enoughToRead ? (
356	                  <>
357	                    Too few ratings in either bucket to read as a signal — this needs at least ten
358	                    on each row before the gap means anything. Right now it is{" "}
359	                    {cleanRated} first-try and {repairedRated} repaired.
360	                  </>
361	                ) : gap !== null && gap >= 10 ? (
362	                  <>
363	                    Thumbs-down is {gap.toFixed(1)} points more likely on builds that needed a
364	                    repair pass. That points at <strong>reliability</strong>: the repair loop is
365	                    shipping something that compiles but limps. Fixing the generator&apos;s first
366	                    try would move both this and the green-build rate on /admin.
367	                  </>
368	                ) : gap !== null && gap <= -10 ? (
369	                  <>
370	                    Thumbs-down is {Math.abs(gap).toFixed(1)} points MORE likely on builds that
371	                    compiled first try — the opposite of the expected shape. Worth checking the
372	                    rating write path before acting on it.
373	                  </>
374	                ) : (
375	                  <>
376	                    Thumbs-down is spread evenly across builds that needed repair and builds that
377	                    did not ({cleanDownRate}% vs {repairedDownRate}%). That points at{" "}
378	                    <strong>quality</strong>, not reliability: the output was mechanically fine and
379	                    still was not what people asked for. Repair-loop work would not move it.
380	                  </>
381	                )}
382	              </p>
383	            </>
384	          )}
385	        </Panel>
386	
387	        <Panel
388	          title="Why people were unhappy"
389	          subtitle="Reason counts across the window. The reason is only offered on a thumbs-down, and it is optional — the closed list lives in app/api/feedback/route.ts."
390	        >
391	          {down === 0 ? (
392	            <Empty>No thumbs-down recorded, so there is nothing to break down.</Empty>
393	          ) : (
394	            <>
395	              <ul className="space-y-2">
396	                {reasonCounts.map((r) => (
397	                  <li key={r.id} className="flex items-center gap-3 text-sm">
398	                    <Link
399	                      href={href({ rating: "down", reason: r.id })}
400	                      className="w-36 shrink-0 rounded underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40"
401	                    >
402	                      {r.label}
403	                    </Link>
404	                    <span className="flex-1">
405	                      <Bar value={r.count} max={maxReason} />
406	                    </span>
407	                    <span className="w-20 shrink-0 text-right tabular-nums text-black/60 dark:text-white/60">
408	                      {r.count}
409	                      {down > 0 ? ` · ${pct(r.count, down)}%` : ""}
410	                    </span>
411	                  </li>
412	                ))}
413	                {noReason > 0 ? (
414	                  <li className="flex items-center gap-3 text-sm">
415	                    <Link
416	                      href={href({ rating: "down", reason: "none" })}
417	                      className="w-36 shrink-0 rounded text-black/50 underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:text-white/50 dark:focus-visible:ring-white/40"
418	                    >
419	                      No reason given
420	                    </Link>
421	                    <span className="flex-1">
422	                      <Bar value={noReason} max={maxReason} />
423	                    </span>
424	                    <span className="w-20 shrink-0 text-right tabular-nums text-black/60 dark:text-white/60">
425	                      {noReason} · {pct(noReason, down)}%
426	                    </span>
427	                  </li>
428	                ) : null}
429	              </ul>
430	              <p className="mt-3 text-xs text-black/50 dark:text-white/50">
431	                Percentages are of all {down} thumbs-down, including the ones that left no reason —
432	                so the bars sum to less than 100%. A large &ldquo;Other&rdquo; share means the six
433	                buckets have stopped matching what people actually mean.
434	              </p>
435	            </>
436	          )}
437	        </Panel>
438	      </div>
439	
440	      <form method="get" action="/admin/feedback" className="mb-6 flex flex-wrap items-center gap-2">
441	        <label htmlFor="rating-filter" className="text-sm text-black/60 dark:text-white/60">
442	          Rating
443	        </label>
444	        <select id="rating-filter" name="rating" defaultValue={rating} className={controlClass}>
445	          <option value="">All ratings</option>
446	          <option value="down">Thumbs down</option>
447	          <option value="up">Thumbs up</option>
448	        </select>
449	
450	        <label htmlFor="reason-filter" className="text-sm text-black/60 dark:text-white/60">
451	          Reason
452	        </label>
453	        <select id="reason-filter" name="reason" defaultValue={reason} className={controlClass}>
454	          <option value="">All reasons</option>
455	          {REASONS.map((r) => (
456	            <option key={r.id} value={r.id}>
457	              {r.label}
458	            </option>
459	          ))}
460	          <option value="none">No reason given</option>
461	        </select>
462	
463	        <button type="submit" className={buttonClass}>
464	          Filter
465	        </button>
466	        {filtering ? (
467	          <Link
468	            href="/admin/feedback"
469	            className="rounded text-sm text-black/50 underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:text-white/50 dark:focus-visible:ring-white/40"
470	          >
471	            Clear
472	          </Link>
473	        ) : null}
474	      </form>
475	
476	      <Panel
477	        title="Ratings"
478	        subtitle={
479	          <>
480	            {filtering
481	              ? `${filtered.length} of ${ratings.length} ratings in the window match this filter.`
482	              : `${ratings.length} rating(s) in the window.`}
483	            {filtered.length > visible.length ? ` Showing the newest ${visible.length}.` : ""}
484	            {total > ratings.length
485	              ? ` The window itself is the most recent ${WINDOW} ratings of ${total}.`
486	              : ""}{" "}
487	            Prompts and generated files are never shown here — a rating is telemetry, not a copy of
488	            customer content.
489	          </>
490	        }
491	      >
492	        {visible.length === 0 ? (
493	          <Empty>
494	            {total === 0 ? (
495	              <>
496	                No build ratings have been recorded at all. This is an empty table, not a happy
497	                customer base — see the note at the top of the page.
498	              </>
499	            ) : filtering ? (
500	              <>No ratings in the window match this filter.</>
501	            ) : (
502	              <>No ratings in the window.</>
503	            )}
504	          </Empty>
505	        ) : (
506	          <TableFrame>
507	            <thead>
508	              <tr className="border-b border-black/10 text-xs text-black/50 dark:border-white/10 dark:text-white/50">
509	                <Th>When</Th>
510	                <Th>Rating</Th>
