"use client";

import { useState } from "react";

// Thumbs up/down on the build that just finished.
//
// Kept deliberately small and easy to ignore. The moment someone has a working
// site is the moment they want to look at it, not fill in a survey — a modal
// here would buy a few more data points at the cost of the thing they came for.
//
// Thumbs-down opens a short reason list, because "it's bad" is not actionable
// and "the copy is generic" is. Thumbs-up submits immediately and stops: there
// is nothing to follow up on, and asking anyway reads as fishing.

const REASONS: { id: string; label: string }[] = [
  { id: "looks-generic", label: "Looks generic" },
  { id: "wrong-content", label: "Wrong content" },
  { id: "layout-off", label: "Layout is off" },
  { id: "missing-something", label: "Missing something" },
  { id: "broken", label: "Something's broken" },
  { id: "other", label: "Other" },
];

export default function BuildRating({ buildId }: { buildId: string }) {
  const [rating, setRating] = useState<"up" | "down" | null>(null);
  const [done, setDone] = useState(false);

  async function send(value: "up" | "down", reason?: string) {
    setRating(value);
    if (value === "up" || reason) setDone(true);

    // Fire and forget. A failed rating must never surface an error to someone
    // who was only trying to be helpful — it is our telemetry, not their task.
    try {
      await fetch("/api/feedback", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ buildId, rating: value, reason }),
      });
    } catch {
      // ignored on purpose — see above
    }
  }

  if (done) {
    return <p className="text-xs text-black/40 dark:text-white/40">Thanks — noted.</p>;
  }

  if (rating === "down") {
    return (
      <div className="flex flex-col gap-1.5">
        <p className="text-xs text-black/40 dark:text-white/40">What was off?</p>
        <div className="flex flex-wrap gap-1.5">
          {REASONS.map((r) => (
            <button
              key={r.id}
              onClick={() => send("down", r.id)}
              className="rounded-full border border-black/10 px-2.5 py-1 text-xs text-black/60 hover:border-black/30 hover:text-black focus-visible:ring-2 focus-visible:ring-black/30 focus-visible:outline-none dark:border-white/10 dark:text-white/60 dark:hover:border-white/30 dark:hover:text-white"
            >
              {r.label}
            </button>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="flex items-center gap-2">
      <span className="text-xs text-black/40 dark:text-white/40">Was this what you wanted?</span>
      <button
        onClick={() => send("up")}
        aria-label="Yes, this is what I wanted"
        className="rounded-md px-1.5 py-0.5 text-sm text-black/40 hover:bg-black/5 hover:text-black focus-visible:ring-2 focus-visible:ring-black/30 focus-visible:outline-none dark:text-white/40 dark:hover:bg-white/5 dark:hover:text-white"
      >
        👍
      </button>
      <button
        onClick={() => send("down")}
        aria-label="No, this missed the mark"
        className="rounded-md px-1.5 py-0.5 text-sm text-black/40 hover:bg-black/5 hover:text-black focus-visible:ring-2 focus-visible:ring-black/30 focus-visible:outline-none dark:text-white/40 dark:hover:bg-white/5 dark:hover:text-white"
      >
        👎
      </button>
    </div>
  );
}
