const fs = require("fs");
const raw = fs.readFileSync(process.argv[2], "utf8");
const rows = (raw.match(/2026-08-\d\d \d\d:\d\d:\d\d/g) || []).length;
const txt = raw
  .replace(/<script[\s\S]*?<\/script>/g, "")
  .replace(/<[^>]+>/g, "\n")
  .replace(/&#x27;/g, "'")
  .replace(/&amp;/g, "&")
  .replace(/&quot;/g, '"');
const lines = txt.split("\n").map((s) => s.trim()).filter(Boolean);
const fi = lines.indexOf("Filter");
const ri = lines.indexOf("Ratings", fi >= 0 ? fi : 0);
console.log("   subtitle:", lines[ri + 1]);
console.log("   table rows:", rows);
const sel = [...raw.matchAll(/<option value="([^"]*)" selected=""/g)].map((m) => m[1]);
console.log("   selected options:", JSON.stringify(sel));
const empty = lines.find((l) => l.startsWith("No ratings in the window"));
if (empty) console.log("   empty:", empty);

