// Step 2 of cleanup: remove every SupportNote created by a verification run.
// Both authors are throwaway admins (this run's, and the previous agent's
// leftover), so scoping by authorEmail cannot touch anything genuine.
const { PrismaClient } = require("C:/Users/edmem/kodely-prod/node_modules/@prisma/client");
const db = new PrismaClient();
const AUTHORS = ["zz-feedback-verify-admin@example.invalid", "inbox-verify-admin@kodely.local"];
(async () => {
  const before = await db.supportNote.count();
  const r = await db.supportNote.deleteMany({ where: { authorEmail: { in: AUTHORS } } });
  const remaining = await db.supportNote.findMany({ select: { authorEmail: true, body: true } });
  console.log("notes before:", before, "deleted:", r.count, "remaining:", remaining.length);
  for (const n of remaining) console.log("  LEFT:", n.authorEmail, JSON.stringify(n.body.slice(0, 60)));
  await db.$disconnect();
})().catch((e) => { console.error(e); process.exit(1); });

const { PrismaClient } = require("C:/Users/edmem/kodely-prod/node_modules/@prisma/client");
const db = new PrismaClient();
(async () => {
  const rows = await db.adminAuditLog.groupBy({
    by: ["actorEmail", "action"],
    _count: { _all: true },
  });
  console.log("AdminAuditLog by actor/action:");
  for (const r of rows) console.log("  ", r.actorEmail, r.action, r._count._all);
  console.log("total", await db.adminAuditLog.count());
  await db.$disconnect();
})().catch((e) => { console.error(e); process.exit(1); });

// Final cleanup: audit rows this verification run wrote, plus the throwaway
// accounts (mine, and the previous agent's leftover inbox-verify admin).
// Sessions cascade with the user. Parallel agents' zz-flags-*/zz-td-*/zz-sites-*
// rows are deliberately untouched.
const { PrismaClient } = require("C:/Users/edmem/kodely-prod/node_modules/@prisma/client");
const db = new PrismaClient();

const MY_ACTOR = "zz-feedback-verify-admin@example.invalid";
const MY_USERS = [
  "zz-feedback-verify-admin@example.invalid",
  "zz-feedback-verify-customer@example.invalid",
  "inbox-verify-admin@kodely.local",
];

(async () => {
  const audit = await db.adminAuditLog.deleteMany({ where: { actorEmail: MY_ACTOR } });
  console.log("adminAuditLog deleted:", audit.count);

  const users = await db.user.findMany({ where: { email: { in: MY_USERS } }, select: { id: true, email: true } });
  for (const u of users) {
    const sess = await db.session.count({ where: { userId: u.id } });
    await db.user.delete({ where: { id: u.id } });
    console.log("deleted user:", u.email, "(sessions cascaded:", sess + ")");
  }

  console.log("--- final state ---");
  console.log("build.rated events:", await db.event.count({ where: { name: "build.rated" } }));
  console.log("supportNotes:", await db.supportNote.count());
  console.log("adminAuditLog rows left:", await db.adminAuditLog.count());
  console.log(
    "users left:",
    JSON.stringify((await db.user.findMany({ select: { email: true, role: true }, orderBy: { createdAt: "asc" } }))),
  );
  await db.$disconnect();
})().catch((e) => { console.error(e); process.exit(1); });

