1	"use server";
2	
3	import { refresh } from "next/cache";
4	import { db } from "@/lib/db";
5	import { getAdminUser } from "@/lib/auth";
6	import { ADMIN_ACTIONS, ADMIN_TARGET_TYPES, adminActionRow } from "@/lib/admin-audit";
7	import { NOTE_MAX, type NoteFormState } from "./ui";
8	
9	// Writing a support note is the only mutation this inbox performs. Everything
10	// else on these pages reads.
11	//
12	// A "use server" file may only export async functions, so NOTE_MAX and the
13	// form-state type live in ./ui.tsx and are imported (the type as a type-only
14	// import, so nothing React-shaped is dragged into the action bundle).
15	
16	export async function addSupportNote(
17	  _prev: NoteFormState,
18	  formData: FormData,
19	): Promise<NoteFormState> {
20	  // Server Functions are reachable by direct POST, not only through this UI —
21	  // so the admin check happens HERE, not merely on the page that renders the
22	  // form. Same reason getAdminUser() is called on every admin page: a layout
23	  // is not an authorization boundary.
24	  const admin = await getAdminUser();
25	  if (!admin) return { error: "You are not signed in as an admin.", ok: false };
26	
27	  const rawUserId = formData.get("userId");
28	  const rawBody = formData.get("body");
29	  const userId = typeof rawUserId === "string" ? rawUserId : "";
30	  const body = typeof rawBody === "string" ? rawBody.trim() : "";
31	
32	  if (!userId) return { error: "Missing the customer this note is about.", ok: false };
33	  if (!body) return { error: "A note needs something in it.", ok: false };
34	  if (body.length > NOTE_MAX) {
35	    return {
36	      error: `That is ${body.length} characters — keep a note under ${NOTE_MAX}. Summarise rather than paste.`,
37	      ok: false,
38	    };
39	  }
40	
41	  // Verify the target exists rather than letting the foreign key throw: a 500
42	  // on a stale tab is a worse answer than a sentence.
43	  const user = await db.user.findUnique({ where: { id: userId }, select: { id: true } });
44	  if (!user) return { error: "That customer no longer exists.", ok: false };
45	
46	  // The note and its audit row go in together or not at all. adminActionRow
47	  // (rather than recordAdminAction) exists for exactly this: a write that must
48	  // be atomic with the mutation it records, so there can be no note whose
49	  // authorship the log does not account for, and no log row for a note that
50	  // rolled back. An interactive transaction rather than the array form because
51	  // the row's meta carries the new note's id, which does not exist until the
52	  // insert has run.
53	  //
54	  // meta holds the ID ONLY. The note body is already disclosable in a
55	  // data-subject access request; copying its text into the audit log would
56	  // double the exposure and double the number of places it has to be found and
57	  // redacted. The id is enough to join back to the note itself.
58	  await db.$transaction(async (tx) => {
59	    const note = await tx.supportNote.create({
60	      // authorEmail comes from the session, never from the form. Attribution
61	      // nobody can spoof is the whole point of recording it.
62	      data: { userId: user.id, authorEmail: admin.email, body },
63	      select: { id: true },
64	    });
65	    await tx.adminAuditLog.create({
66	      data: adminActionRow(admin, ADMIN_ACTIONS.supportNoteAdded, {
67	        targetType: ADMIN_TARGET_TYPES.user,
68	        targetId: user.id,
69	        meta: { noteId: note.id },
70	      }),
71	    });
72	  });
73	
74	  // Re-render the current route so the new note appears above the form without
75	  // a manual reload.
76	  refresh();
77	
78	  return { error: null, ok: true };
79	}
